#!/usr/bin/env node
// Lossless packaging of Master's supplied Luna character grids. No image processing.
import fs from "node:fs";
import { fileURLToPath } from "node:url";
import { format } from "prettier";

const root = new URL("../../../", import.meta.url);
const sources = [
  ["luna-56x28-v01.cells.json", "SPLASH_PORTRAIT", 56, 28],
  ["luna-72x36-v01.cells.json", "SPLASH_PORTRAIT_LARGE", 72, 36],
];
let output =
  "// GENERATED by scripts/generate-splash.mjs from the supplied Luna v0.1 grids.\n";
for (const [filename, name, cols, height] of sources) {
  const source = JSON.parse(
    fs.readFileSync(
      new URL(`docs/tui/assets/luna-braille-v01/${filename}`, root),
      "utf8",
    ),
  );
  if (
    source.width !== cols ||
    source.height !== height ||
    source.rows.length !== height
  )
    throw Error(`INVALID_LUNA_DIMENSIONS: ${filename}`);
  const palette = [],
    cells = [],
    ink = [];
  for (const row of source.rows) {
    if (row.length !== cols) throw Error(`INVALID_LUNA_ROW: ${filename}`);
    let chars = "",
      indices = "";
    for (const cell of row) {
      if (!/^[ \u2800-\u28ff]$/u.test(cell.char))
        throw Error("INVALID_LUNA_CHARACTER");
      chars += cell.char;
      if (cell.fg === null) {
        if (cell.char !== " " && cell.char !== "\u2800")
          throw Error("MISSING_LUNA_COLOR");
        indices += "  ";
        continue;
      }
      if (
        !Array.isArray(cell.fg) ||
        cell.fg.length !== 3 ||
        !cell.fg.every((c) => Number.isInteger(c) && c >= 0 && c <= 255)
      )
        throw Error("INVALID_LUNA_COLOR");
      const hex =
        "#" + cell.fg.map((c) => c.toString(16).padStart(2, "0")).join("");
      let slot = palette.indexOf(hex);
      if (slot < 0) {
        slot = palette.length;
        palette.push(hex);
      }
      if (slot > 255) throw Error("LUNA_PALETTE_OVERFLOW");
      indices += slot.toString(16).padStart(2, "0");
    }
    cells.push(chars);
    ink.push(indices);
  }
  output += `// Source: ${filename}; two hex digits per color index, two spaces for unpainted cells.\n`;
  output += `export const ${name} = ${JSON.stringify({ cols, palette, cells, ink })} as const;\n`;
}
output = await format(output, { parser: "typescript" });
const target = fileURLToPath(
  new URL("src/pi_secretary/src/tui/splash-art.ts", root),
);
if (process.argv.includes("--check")) {
  if (fs.readFileSync(target, "utf8") !== output)
    throw Error("SPLASH_ASSETS_OUT_OF_DATE");
} else fs.writeFileSync(target, output);
